"""Consolida acuerdos vigentes y evidencia de regresión; no cambia producto ni despliega."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
items=[]
def add(id,phase,title,status,work,accept,deps='',evidence='Acuerdo del propietario en este chat'):
 items.append(dict(id=id,etapa=phase,funcion=title,estado=status,trabajo=work,aceptacion=accept,dependencias=deps,evidencia=evidence))
add('F01','1. Estabilización','Fichas públicas de negocios','Error confirmado: HTTP 503','Corregir resolución de configuración/conexión del renderizador y comprobar paridad del paquete. Un borrador devuelve 404 sin datos.','Ficha publicada con suscripción habilitante carga; ficha gratuita aparece en directorio según sus beneficios; borrador permanece privado.','','PB-02, AZ-03; no afirmar fuga de datos: actualmente se observó 503.')
add('F02','1. Estabilización','Una política consistente de publicación de lugares','Discrepancia por investigar','Contrastar estado de BD, catálogo, filtros del listado y decisiones editoriales; unificar su interpretación sin publicar lugares no aprobados.','Listado y rutas reflejan exactamente lugares autorizados. Mantener privados Sonsón/Cauca Viejo y otros borradores si no tienen aprobación.','Aprobaciones editoriales existentes','LU-01: Bogotá figura publicada en BD local pero falta en el listado. No permite concluir que deba publicarse.')
add('F03','1. Estabilización','Regresión fiable y reproducible','Parcial','Separar dependencias y bloqueos por antiabuso de fallos funcionales; evitar que recuperación bloqueada cause falsos diagnósticos en casos siguientes; mantener versiones de informes.','Pruebas independientes con datos propios, limpieza y fallos localizables. No desactivar protecciones del portal.','','Informes completos y parciales tienen distinta fecha y alcance; AD-16 ya pasó en el parcial corregido.')
add('F04','2. Identidad','Crear cuenta personal y validar correo','Falta activación','Alta de persona única sin elegir viajero/negocio. Correo de verificación con token opaco, hash, vencimiento y un solo uso; reenvío limitado.','No se considera cuenta verificada hasta usar enlace válido; tokens alterados/vencidos/usados rechazados; no duplicar cuenta.','Configuración de correo transaccional; buzón local en preprod','CU-02/03/04; registerTraveler crea active sin validar correo.')
add('F05','2. Identidad','Mi cuenta: Personal / Mis negocios','Pendiente de reestructurar','Eliminar selector Explorar/Mis negocios posterior al acceso. Mantener navegación en página de origen tras login modal. Portal de cuenta con dos pestañas.','Datos y seguridad en Personal; negocios, solicitudes, suscripciones, pagos, soportes, métricas y cancelaciones se conservan en Mis negocios. Perfil de viajero futuro sin funciones ficticias.','F04','AU-04 y decisiones de navegación; login existente conserva selector de espacio.')
add('F06','2. Identidad','Cuenta junto a idiomas','Pendiente','Nombre y Mi cuenta a la izquierda de ES/EN/PT, en fila existente; quitar franja adicional; logout en menú y Administración solo para rol autorizado.','Sin sesión: Iniciar sesión. Con sesión: nombre/Mi cuenta. Comprobar escritorio, móvil e idiomas.','F05')
add('F07','2. Identidad','Recuperación y correo en producción','Existe parcialmente; falta cierre','Conservar flujo de restablecimiento existente; confirmar proveedor/remitente/origen canónico, entrega y expiración; alinear textos con cuenta personal.','Nueva clave funciona, antigua rechazada, confirmación obligatoria, token único/vencido rechazado y errores sin enumerar cuentas.','Configuración transaccional real','RC-01 pasó en ejecución previa; última completa afectada por repeticiones. No declarar recuperación inexistente.')
add('F08','3. Negocios','Crear y reclamar con la misma cuenta','Parcial','Conservar identidad personal, negocios múltiples, búsqueda por nombre/lugar/categorías y formulario con mapa; ninguna solicitud duplica establecimiento.','Alta nueva y reclamación guardadas para cuenta actual, sin pedir otra contraseña ni crear otra persona.','F04/F05','NG-01/02/03 pasan; no rehacer lo implementado.')
add('F09','3. Negocios','Validación automática sin impedir guardar','No implementada','Separar cuenta, existencia del negocio, control del canal y autorización de administración. Conector RNT; evaluar RUES autorizado. Estados verificables, reintentos y excepciones.','Se puede guardar aunque API falle/no encuentre. Vinculación y publicación según comprobaciones explícitas. Pagar no sustituye comprobar representación.','Acceso/condiciones del proveedor; política final de publicación','NG-04. Investigación identificó API abierta RNT y proveedores RUES; no hay contrato ni cobertura comprobada.')
add('F10','3. Negocios','Reclamación de negocio ya asociado','Falta guardar controversia','Recibir declaración y evidencia, guardar revisión, conservar propietario y negar edición hasta resolución.','Dos cuentas distintas: solicitante ve su estado; dueño conserva acceso; resolución auditada; sin duplicar ficha.','F08/F09','NG-05: se rechaza en vez de guardar solicitud.')
add('F11','4. Suscripción','Tabla resumida seleccionable al crear negocio','Falta UI y persistencia en alta','Opciones radio: Gratuito y cuatro pagas — Básico, Tarjeta Ampliada, Página Comercial, Premium. Beneficio principal y precio desde catálogo real.','Una opción seleccionada; total consistente y elección persistida con la solicitud; no activar beneficios por selección.','F08','SU-01. Último acuerdo reafirma cuatro pagas además de Gratuito; no eliminar Básico.')
add('F12','4. Suscripción','Mensual/trimestral/semestral/anual','Backend parcial; UI y tarifas incompletas','Mostrar frecuencias válidas, cotización del servidor y total. Gratis sin frecuencia de cobro.','No confiar en precio del navegador; importes persistidos coinciden; sin tarifa configurada no ofrecer cobro inventado.','Definir importes trimestrales/semestrales','SU-02/03. BusinessSubscriptionAdminService y esquema ya contemplan quarterly/semiannual; UI actual solo monthly/annual.')
add('F13','4. Suscripción','Instrucciones reales de pago','Faltan configuración y presentación','Panel/configuración privada de métodos y pantalla con QR, llave o número/tipo de cuenta disponibles, beneficiario y referencia. Conservar soporte privado y revisión existentes.','Gratis no exige pago; suscripción paga muestra solo medios configurados; soporte no publica ni acredita pago automáticamente.','Datos bancarios/QR reales; F11/F12','PG-01/02. Actualmente remite a pedir instrucciones por correo; no inventar medios. Confirmar significado exacto de multibanco antes de integrar proveedor.')
add('F14','4. Suscripción','Complemento opcional de experiencias','Definido conceptualmente, no implementado','Si ofrece experiencias y hay experiencias publicadas en el mismo lugar, permitir selección y complemento separado de suscripción. Validar relación del lado del servidor.','Un negocio multcategoría mantiene una ficha; vínculo visible solo a experiencias elegidas/habilitadas del lugar; subtotal y vigencia propios; sin experiencias elegibles no se ofrece compra.','Definir precio, por experiencia o conjunto, duración, suscripciones elegibles y evidencia del operador','Acuerdos recientes. No crear una quinta suscripción ni duplicar negocios.')
add('F15','5. Público y contacto','Navegación pública sin pérdida de enlaces','Auditoría lista; reestructuración pendiente','Lugares / Planea tu visita / Estamos creciendo / Para negocios. Logo a inicio. Experiencias dentro del lugar después de atractivos. Preservar todas las páginas inventariadas, idiomas y compatibilidad.','Mapa antes/después sin páginas huérfanas ni enlaces rotos; tres pestañas Cobertura/Audiencia/Haz parte y porcentaje/compartir se conservan.','F05/F06; auditoria/mapa-navegacion.html')
add('F16','5. Público y contacto','Tres contactos diferenciados','Dos recorridos existen; PQRS falta','Mantener negocio y promotor separados. Crear contacto de usuario: sugerencia/petición/queja/reclamo con recepción persistida, referencia, consulta interna y respuesta.','Sin cuenta puede registrar; confirmación real y referencia; no mezclar con campañas o reclamación de propiedad; consentimiento adecuado.','Definir operación de atención y seguimiento','CT-01/02 pasaron antes del bloqueo por límite; CT-03 pendiente.')
add('F17','5. Público y contacto','Contenido de lugares y directorio','Existe; revisar por lugar','Conservar historia, atractivos, experiencias, eventos y categorías/directorio. Comprobar comercios publicados, filtros, estados vacíos y navegación de fichas por suscripción.','Jericó conserva tres experiencias. Lugares sin experiencias válidas muestran estado adecuado, sin inventarlas ni exigir contenido idéntico a todos.','F01/F02','LU: historia/directorio pasan; Jericó experiencias pasa. Otros lugares requieren revisión editorial, no función nueva automática.')
add('F18','6. Cierre y calidad','Operaciones administrativas completas','Acceso aprobado; cobertura funcional pendiente','Añadir fixtures para CRUD de lugares/negocios/canales, importación/actualización por ID, suscripciones/soportes/aprobación, costos/evidencias, cancelaciones, permisos y documentos privados; probar campañas sin envío real y migraciones solo sobre BD desechable.','Persistencia correcta, sin duplicados ni acceso entre cuentas; errores y reversión comprobados; no ejecutar SQL de pruebas sobre datos compartidos.','Diseñar casos específicos por módulo','14 accesos, herramientas complementarias y rechazo sin rol ya pasan. No confundir acceso con operación.')
add('F19','6. Cierre y calidad','Reportes administrativos','Solo anuncio Próximamente','Definir si hace falta módulo adicional a estadísticas públicas e inteligencia privada; implementar solo reportes acordados.','Ninguna entrada anunciada como funcional sin contenido; no duplicar métricas ni prometer informes no definidos.','Definir alcance de reportes','AD-17')
add('F20','6. Cierre y calidad','Regresión de navegador y puerta de salida','Parcial','Automatizar modal/idiomas/tabs, formularios, mapas y directorio en escritorio/móvil. Completar casos pendientes y conectar control al proceso de publicación.','Informe del mismo candidato sin fallos ni pendientes aplicables, limpieza correcta y aprobación humana; despliegue desde preprod aprobado y merge posterior a main.','F01–F18 aplicables; decisiones F19','Scripts actuales informan NO LISTO, pero todavía no son bloqueo obligatorio del despliegue. OAuth Google/Microsoft/Facebook y perfil avanzado de viajero siguen aplazados.')
report={'fecha':'2026-10-17','rama':'preprod','alcance':'Lista de implementación, no declaración de entrega. No modifica producción ni sustituye aprobaciones.','items':items,'decisiones_pendientes':['Precios trimestrales y semestrales','Precio y unidad de cobro del complemento de experiencias, vigencia y suscripciones elegibles','Proveedor/acceso de validación y comprobación del vínculo de la persona','Medios de pago reales y significado/proveedor de QR multibanco','Necesidad y alcance de reportes administrativos adicionales']}
out=ROOT/'auditoria';(out/'pendientes-implementacion.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
e=lambda x:html.escape(str(x))
body='<h1>Funciones pendientes para implementar</h1><p>17 de octubre de 2026 · preprod. Basado en acuerdos, código y regresión. No se cambió navegación ni producción.</p><p><strong>Orden:</strong> estabilizar → identidad → negocios → suscripciones → navegación/contacto → cierre. Dentro de una etapa se respetan dependencias.</p><input id="q" placeholder="Buscar función, estado o prueba" aria-label="Buscar pendientes"><p>El rojo del informe de pruebas no siempre significa que falte una función: puede ser un límite antiabuso, un caso dependiente o una discrepancia editorial. Aquí se distingue.</p>'
for i in items:
 body+='<article><h2>'+e(i['id']+' · '+i['funcion'])+'</h2><p><b>'+e(i['etapa'])+'</b> — '+e(i['estado'])+'</p><p>'+e(i['trabajo'])+'</p><p><b>Se acepta cuando:</b> '+e(i['aceptacion'])+'</p><p><b>Dependencias:</b> '+e(i['dependencias'] or 'Ninguna decisión adicional identificada')+'</p><p><b>Evidencia:</b> '+e(i['evidencia'])+'</p></article>'
body+='<h2>Decisiones pendientes</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in report['decisiones_pendientes'])+'</ul><p>Se puede avanzar en las demás funciones sin esperar estas decisiones. No inventar precios, permisos, proveedores o medios bancarios.</p>'
(out/'pendientes-implementacion.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><title>Pendientes de implementación</title><style>body{font:16px/1.6 system-ui;max-width:1050px;margin:40px auto;padding:20px;background:#fffaf4;color:#302d29}article{border:1px solid #d8cabc;padding:20px;margin:20px 0;border-radius:12px;background:white}h2{font-size:21px}input{padding:14px;width:90%}</style>'+body+'<script>document.querySelector("#q").oninput=e=>{for(const a of document.querySelectorAll("article"))a.hidden=!a.textContent.toLowerCase().includes(e.target.value.toLowerCase())}</script></html>')
print('20 funciones consolidadas: auditoria/pendientes-implementacion.html y JSON')
